// PluginSubcommand Determines what action is taken: - *subcommand* **start** takes a *path* to an executable as argument and starts it as plugin. *path* may be an absolute path or a path relative to the plugins directory (default *~/.lightning/plugins*). If the plugin is already running and the executable (checksum) has changed, the plugin is killed and restarted except if its an important (or builtin) plugin. If the plugin doesn't complete the 'getmanifest' and 'init' handshakes within 60 seconds, the command will timeout and kill the plugin. Additional *options* may be passed to the plugin, but requires all parameters to be passed as keyword=value pairs using the `-k|--keyword` option which is recommended. For example the following command starts the plugin helloworld.py (present in the plugin directory) with the option greeting set to 'A crazy': ```shell lightning-cli -k plugin subcommand=start plugin=helloworld.py greeting='A crazy' ``` - *subcommand* **stop** takes a plugin executable *path* or *name* as argument and stops the plugin. If the plugin subscribed to 'shutdown', it may take up to 30 seconds before this command returns. If the plugin is important and dynamic, this will shutdown `lightningd`. - *subcommand* **startdir** starts all executables it can find in *directory* (excl. subdirectories) as plugins. Checksum and timeout behavior as in **start** applies. - *subcommand* **rescan** starts all plugins in the default plugins directory (default *~/.lightning/plugins*) that are not already running. Checksum and timeout behavior as in **start** applies. - *subcommand* **list** lists all running plugins (incl. non-dynamic).
type PluginSubcommand string

const (
	PluginSubcommandStart    PluginSubcommand = "start"
	PluginSubcommandStop     PluginSubcommand = "stop"
	PluginSubcommandRescan   PluginSubcommand = "rescan"
	PluginSubcommandStartdir PluginSubcommand = "startdir"
	PluginSubcommandList     PluginSubcommand = "list"
)

type PluginRequest struct {
	// Directory *path* of a directory containing plugins.
	Directory string   `json:"directory,omitempty"`
	Options   []string `json:"options,omitempty"`
	// Plugin *path* or *name* of a plugin executable to start or stop.
	Plugin string `json:"plugin,omitempty"`
	// Subcommand Determines what action is taken: - *subcommand* **start** takes a *path* to an executable as argument and starts it as plugin. *path* may be an absolute path or a path relative to the plugins directory (default *~/.lightning/plugins*). If the plugin is already running and the executable (checksum) has changed, the plugin is killed and restarted except if its an important (or builtin) plugin. If the plugin doesn't complete the 'getmanifest' and 'init' handshakes within 60 seconds, the command will timeout and kill the plugin. Additional *options* may be passed to the plugin, but requires all parameters to be passed as keyword=value pairs using the `-k|--keyword` option which is recommended. For example the following command starts the plugin helloworld.py (present in the plugin directory) with the option greeting set to 'A crazy': ```shell lightning-cli -k plugin subcommand=start plugin=helloworld.py greeting='A crazy' ``` - *subcommand* **stop** takes a plugin executable *path* or *name* as argument and stops the plugin. If the plugin subscribed to 'shutdown', it may take up to 30 seconds before this command returns. If the plugin is important and dynamic, this will shutdown `lightningd`. - *subcommand* **startdir** starts all executables it can find in *directory* (excl. subdirectories) as plugins. Checksum and timeout behavior as in **start** applies. - *subcommand* **rescan** starts all plugins in the default plugins directory (default *~/.lightning/plugins*) that are not already running. Checksum and timeout behavior as in **start** applies. - *subcommand* **list** lists all running plugins (incl. non-dynamic).
	Subcommand PluginSubcommand `json:"subcommand"`
}

// PluginCommand The subcommand this is responding to.
type PluginCommand string

const (
	PluginCommandStart    PluginCommand = "start"
	PluginCommandStop     PluginCommand = "stop"
	PluginCommandRescan   PluginCommand = "rescan"
	PluginCommandStartdir PluginCommand = "startdir"
	PluginCommandList     PluginCommand = "list"
)

